// HasAd applies the HasEdge predicate on the "ad" edge.
func HasAd() predicate.AdLocalization {
	return predicate.AdLocalization(func(s *sql.Selector) {
		step := sqlgraph.NewStep(
			sqlgraph.From(Table, FieldID),
			sqlgraph.Edge(sqlgraph.M2O, true, AdTable, AdColumn),
		)
		sqlgraph.HasNeighbors(s, step)
	})
}

// HasAdWith applies the HasEdge predicate on the "ad" edge with a given conditions (other predicates).
func HasAdWith(preds ...predicate.Ad) predicate.AdLocalization {
	return predicate.AdLocalization(func(s *sql.Selector) {
		step := newAdStep()
		sqlgraph.HasNeighborsWith(s, step, func(s *sql.Selector) {
			for _, p := range preds {
				p(s)
			}
		})
	})
}

